-- Disposable validation database only; two-tenant contact, outbox and RLS regressions.
begin;
create schema contact_test;
create function contact_test.ok(value boolean,label text) returns void language plpgsql as $$begin
 if value is distinct from true then raise exception 'FAIL: %',label; end if;
 raise notice 'ok - contact: %',label;
end$$;
create function contact_test.fails(command text,label text) returns void language plpgsql as $$begin
 begin execute command;exception when others then raise notice 'ok - contact: % (refused)',label;return;end;
 raise exception 'FAIL: % was permitted',label;
end$$;
grant usage on schema contact_test to anon,authenticated,service_role;
grant execute on all functions in schema contact_test to anon,authenticated,service_role;
insert into auth.users(id,email) values('ca000000-0000-4000-8000-000000000001','contact-a@example.test'),('ca000000-0000-4000-8000-000000000002','contact-b@example.test');
insert into public.organizations(id,name,slug) values('ca000000-0000-4000-8000-000000000011','Contact A','contact-test-a'),('ca000000-0000-4000-8000-000000000012','Contact B','contact-test-b');
insert into public.organization_members(organization_id,user_id,role,status) values('ca000000-0000-4000-8000-000000000011','ca000000-0000-4000-8000-000000000001','owner','active'),('ca000000-0000-4000-8000-000000000012','ca000000-0000-4000-8000-000000000002','owner','active');
insert into public.websites(id,organization_id,name,status,live_url) values('ca000000-0000-4000-8000-000000000021','ca000000-0000-4000-8000-000000000011','Contact A','live','https://contact-a.example.com'),('ca000000-0000-4000-8000-000000000022','ca000000-0000-4000-8000-000000000012','Contact B','live','https://contact-b.example.com');
insert into public.website_contact_settings(website_id,organization_id,notification_email,allowed_origins,enabled) values('ca000000-0000-4000-8000-000000000021','ca000000-0000-4000-8000-000000000011','a@example.test',array['https://contact-a.example.com'],true),('ca000000-0000-4000-8000-000000000022','ca000000-0000-4000-8000-000000000012','b@example.test',array['https://contact-b.example.com'],true);
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000031',repeat('a',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/');
select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000031',repeat('a',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/');
select public.capture_website_lead('ca000000-0000-4000-8000-000000000022','https://contact-b.example.com','ca000000-0000-4000-8000-000000000032',repeat('b',64),'{"name":"Beta","email":"other@example.test"}','B note','inquiries','https://contact-b.example.com/');
select contact_test.ok((select count(*)=2 from public.leads where website_id in ('ca000000-0000-4000-8000-000000000021','ca000000-0000-4000-8000-000000000022')),'duplicate submission creates one lead per website');
select contact_test.ok((select count(*)=2 from public.lead_events where kind='received'),'exactly one received event');
select contact_test.ok((select count(*)=2 from public.provisioning_jobs where kind='lead.notify'),'outbox committed atomically with lead');
select contact_test.ok((select recipient='a@example.test' from public.lead_notifications where organization_id='ca000000-0000-4000-8000-000000000011'),'recipient comes from settings');
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000031',repeat('b',64),'{"name":"Changed","email":"visitor@example.test"}','Changed note','inquiries','https://contact-a.example.com/')$q$,'changed duplicate rejected');
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-b.example.com','ca000000-0000-4000-8000-000000000033',repeat('c',64),'{"name":"Forged","email":"visitor@example.test"}','A note','inquiries','https://contact-b.example.com/')$q$,'wrong origin cannot route lead');
select set_config('contact_test.b_lead',(select id::text from public.leads where organization_id='ca000000-0000-4000-8000-000000000012'),true);
reset role;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','ca000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select contact_test.ok((select count(*)=1 from public.leads),'tenant A list and search cannot see B');
select contact_test.ok((select count(*)=0 from public.leads where contact->>'name'='Beta'),'tenant A search cannot see B');
select contact_test.ok((select count(*)=0 from public.leads where id=current_setting('contact_test.b_lead')::uuid),'known cross-tenant lead ID cannot be fetched');
with modified as (update public.leads set status='won' where id=current_setting('contact_test.b_lead')::uuid returning id) select contact_test.ok((select count(*)=0 from modified),'known cross-tenant lead cannot be updated');
select contact_test.ok((select count(*)=1 from public.lead_events),'tenant A activity cannot see B');
select contact_test.ok((select count(*)=1 from public.lead_notifications),'tenant A notification details cannot see B');
select contact_test.ok((select count(*)=1 from public.website_contact_settings),'tenant A settings cannot see B');
select contact_test.fails($q$update public.leads set message='rewritten'$q$,'captured inquiry immutable to customers');
select contact_test.fails($q$update public.leads set metadata='{"tenant":"forged"}'$q$,'metadata immutable to customers');
select contact_test.fails($q$insert into public.lead_events(lead_id,organization_id,kind,body) select id,organization_id,'note','forged' from public.leads$q$,'events cannot be inserted directly');
select contact_test.fails($q$select public.add_lead_note(current_setting('contact_test.b_lead')::uuid,'forged')$q$,'cross-tenant note refused');
select contact_test.fails($q$select public.configure_website_contact('ca000000-0000-4000-8000-000000000021','a@example.test',null,true,array['https://attacker.example.com'])$q$,'owner cannot register origins');
select public.configure_website_contact('ca000000-0000-4000-8000-000000000021','new-a@example.test','https://calendly.com/example/meeting');
select public.add_lead_note((select id from public.leads),'Contacted visitor manually.');
update public.leads set status='contacted',read_at=now();
select contact_test.ok((select count(*)=3 from public.lead_events),'note and status events recorded');
select contact_test.ok((select read_at is not null from public.leads),'read state update permitted');
select contact_test.ok((select recipient='a@example.test' from public.lead_notifications),'queued recipient immutable after settings change');
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000031',repeat('a',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/')$q$,'customer cannot call service capture function');
reset role;
select set_config('request.jwt.claim.sub','',true);
select set_config('request.jwt.claim.role','anon',true);
set local role anon;
select contact_test.ok((select count(*)=0 from public.leads),'anonymous cannot query leads');
select contact_test.fails('select * from public.lead_events','anonymous cannot query timeline');
select contact_test.fails('select * from public.lead_notifications','anonymous cannot query recipients');
reset role;
select set_config('request.jwt.claim.role','service_role',true);
update public.websites set status='paused' where id='ca000000-0000-4000-8000-000000000021';
set local role service_role;
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000034',repeat('c',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/')$q$,'paused site fails closed');
reset role;
update public.websites set status='live' where id='ca000000-0000-4000-8000-000000000021';
update public.website_contact_settings set enabled=false where website_id='ca000000-0000-4000-8000-000000000021';
set local role service_role;
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000034',repeat('c',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/')$q$,'disabled settings fail closed');
select public.acknowledge_lead_notification(current_setting('contact_test.b_lead')::uuid,'ca000000-0000-4000-8000-000000000012','fixture-mail');
select public.acknowledge_lead_notification(current_setting('contact_test.b_lead')::uuid,'ca000000-0000-4000-8000-000000000012','fixture-mail');
select contact_test.ok((select count(*)=1 from public.lead_events where kind='notification_sent'),'provider acknowledgement and event are atomic and idempotent');
reset role;
update public.website_contact_settings set enabled=true,daily_limit=1 where website_id='ca000000-0000-4000-8000-000000000021';
set local role service_role;
select contact_test.fails($q$select public.capture_website_lead('ca000000-0000-4000-8000-000000000021','https://contact-a.example.com','ca000000-0000-4000-8000-000000000034',repeat('c',64),'{"name":"Alpha","email":"visitor@example.test"}','A note','inquiries','https://contact-a.example.com/')$q$,'site quota rejects additional submissions');
select contact_test.fails($q$insert into public.lead_events(lead_id,organization_id,kind,body) values(current_setting('contact_test.b_lead')::uuid,'ca000000-0000-4000-8000-000000000011','note','forged identity')$q$,'service child row identity cannot cross organizations');
reset role;
rollback;
